  }, [handleOpenCreativeCenter, handleOpenMusicStation]);

  const handleOpenWorks = useCallback(() => {
    navigateTo('/works');
  }, [navigateTo]);

  const handleOpenWorkflows = useCallback(() => {
    navigateTo('/workflows');
  }, [navigateTo]);

  const handleOpenModels = useCallback(() => {
    navigateTo('/#models');
  }, [navigateTo]);

  const handleOpenTemplates = useCallback(() => {
    navigateTo('/#templates');
  }, [navigateTo]);

  const handleOpenAccount = useCallback((nextPath: string) => {
    window.location.assign(`/account?next=${encodeURIComponent(nextPath)}`);
  }, []);

  const handleOpenBoardFromCenter = useCallback(async (boardId: string) => {
    try {
      const workspaceService = WorkspaceService.getInstance();
      await workspaceService.initialize();
      const board = await workspaceService.switchBoard(boardId);
      if (!board) {
        throw new Error('创作空间不存在');
      }
      workspaceService.persistCurrentBoardId(board.id);
      const url = new URL('/', window.location.origin);
      url.searchParams.set(BOARD_URL_PARAM, board.id);
      window.location.assign(url.toString());
    } catch (error) {
      console.error('[App] Failed to open board from creative center:', error);
      MessagePlugin.error({
        content: '画布暂时无法打开，请稍后重试',
        duration: 5000,
        closeBtn: true,
      });
    }
  }, []);

  // Keep ordinary pages in sync with browser back/forward navigation.
  useEffect(() => {
    const handlePopState = async () => {
      if (isHandlingPopStateRef.current) {
        return;
      }

      isHandlingPopStateRef.current = true;

      try {
        setAppLocation(readAppLocation());
        const urlBoardId = getBoardIdFromUrl();

        if (!urlBoardId) {
          setCurrentBoardId(null);
          window.requestAnimationFrame(() => {
            window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
          });
          return;
        }

        // 如果 URL 中的画布 ID 与当前画布不同，则切换
        if (urlBoardId && urlBoardId !== currentBoardId) {
          const workspaceService = WorkspaceService.getInstance();
          const board = await workspaceService.switchBoard(urlBoardId);

          if (board) {
            // skipUrlUpdate: true 因为 URL 已被浏览器更新
            await handleBoardSwitch(board, true);
            // 但仍需持久化 currentBoardId 到 sessionStorage
            workspaceService.persistCurrentBoardId(board.id);
          }
        }
      } catch (error) {
        console.error('[App] Failed to handle browser navigation:', error);
      } finally {
        isHandlingPopStateRef.current = false;
      }
    };

    window.addEventListener('popstate', handlePopState);

    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, [currentBoardId, handleBoardSwitch]);

  // Handle tab sync (when other tab modified data)
  const handleTabSyncNeeded = useCallback(async () => {
    // 设置同步标志，防止同步期间的 onChange 触发保存（保存旧数据覆盖新数据）
    isSyncingRef.current = true;

    try {
      const workspaceService = WorkspaceService.getInstance();
      let currentBoard = workspaceService.getCurrentBoard();

      // 如果画板未加载（getCurrentBoard 返回 null），先通过 switchBoard 加载
      if (!currentBoard) {
        const currentBoardId = workspaceService.getState().currentBoardId;
        if (!currentBoardId) {
          console.warn('[App] handleTabSyncNeeded: no current board ID');
          return;
        }

        // 验证画板是否存在
        if (!workspaceService.getBoardMetadata(currentBoardId)) {
          console.warn(
            '[App] handleTabSyncNeeded: board not found',
            currentBoardId
          );
          return;
        }

        try {
          // 加载画板完整数据
          currentBoard = await workspaceService.switchBoard(currentBoardId);
        } catch (error) {
          console.error(
            '[App] handleTabSyncNeeded: failed to load board',
            error
          );
          return;
        }
      }

      // 使用 reloadBoard 强制从 IndexedDB 重新加载数据（而不是使用缓存）
      const updatedBoard = await workspaceService.reloadBoard(currentBoard.id);

      if (updatedBoard) {
        // 恢复视频 URL
        const elements = await recoverVideoUrlsInElements(
          updatedBoard.elements || []
        );
        const nextData = {
          children: elements,
          viewport: updatedBoard.viewport,
          theme: updatedBoard.theme,
        };
        updateLatestBoardData(
          updatedBoard.id,
          nextData,
          updatedBoard.updatedAt
        );
        hasPendingPersistenceRef.current = false;

        // 更新 React 状态，触发重新渲染
        setValue(nextData);
      }
    } catch (error) {
      console.error('[App] Failed to sync board data:', error);
      // 如果同步失败，降级到刷新页面
      void safeReload();
    } finally {
      // 延迟清除同步标志，等待 React 重渲染完成后 onChange 触发的保存被跳过
      // React 18 的批量更新可能在下一帧才执行，所以使用 setTimeout 确保足够延迟
      setTimeout(() => {
        isSyncingRef.current = false;
      }, 100);
    }
  }, [updateLatestBoardData]);

  // Handle board changes (auto-save)
  const handleBoardChange = useCallback(
    (data: BoardChangeData) => {
      setValue(data);
      // 同步更新最新 viewport
      latestViewportRef.current = data.viewport;

      // 只在数据准备好之后才保存，避免在初始化时保存空数据
      // 使用 ref 而非 state，避免闭包捕获旧值（Wrapper 中 BOARD_TO_AFTER_CHANGE 不会因 onChange 变化而更新）
      if (!isDataReadyRef.current) {
        return;
      }

      // 同步期间不保存，防止用旧数据覆盖其他标签页保存的新数据
      if (isSyncingRef.current) {
        return;
      }

      // 标记本标签页有用户主动修改
      localDirtyRef.current = true;
      hasPendingPersistenceRef.current = true;

      // Save to current board
      const workspaceService = WorkspaceService.getInstance();

      // 额外安全检查：确保当前画板已经完全加载
      const currentBoard = workspaceService.getCurrentBoard();
      if (!currentBoard) {
        console.warn(
          '[App] handleBoardChange: board not fully loaded, skipping save'
        );
        return;
      }

      updateLatestBoardData(currentBoard.id, data);

      workspaceService
        .saveCurrentBoard(data)
        .then(() => {
          hasPendingPersistenceRef.current = false;
          clearBoardCloseSnapshot(currentBoard.id);
          // 通知其他标签页数据已更新
          markTabSyncVersion(currentBoard.id);
        })
        .catch((err: Error) => {
          console.error('[App] Failed to save board:', err);
        });
    },
    [updateLatestBoardData]
  );

  // Handle viewport changes (pan/zoom) - 单独保存 viewport
  const handleViewportChange = useCallback(
    (viewport: Viewport) => {
      // 更新最新 viewport
      latestViewportRef.current = viewport;
      const latestSnapshot = latestBoardDataRef.current;
      if (latestSnapshot) {
        latestBoardDataRef.current = {
          ...latestSnapshot,
          viewport,
          updatedAt: Date.now(),
        };
      }

      // 同步期间不保存 viewport，防止用旧数据覆盖
      if (isSyncingRef.current) {
        return;
      }

      hasPendingPersistenceRef.current = true;

      // 防抖保存
      if (viewportSaveTimerRef.current) {
        clearTimeout(viewportSaveTimerRef.current);
      }
      viewportSaveTimerRef.current = setTimeout(() => {
        // 再次检查同步状态
        if (isSyncingRef.current) {
          return;
        }

        const workspaceService = WorkspaceService.getInstance();
        const currentBoard = workspaceService.getCurrentBoard();
        if (currentBoard) {
          // 只保存 viewport，不影响其他数据
          workspaceService
            .saveCurrentBoard({
              children: currentBoard.elements,
              viewport: viewport,
              theme: currentBoard.theme,
            })
            .then(() => {
              hasPendingPersistenceRef.current = false;
              clearBoardCloseSnapshot(currentBoard.id);
            })
            .catch((err: Error) => {
              console.error('[App] Failed to save viewport:', err);
            });
        }
      }, VIEWPORT_SAVE_DEBOUNCE);
    },
    [updateLatestBoardData]
  );

  // 页面关闭/隐藏前保存当前画布快照，并尽量 flush 到 IndexedDB
  useEffect(() => {
    const flushBoardBeforeLeave = (
      reason: 'visibilitychange' | 'pagehide' | 'beforeunload'
    ) => {
      // 清除防抖定时器
      if (viewportSaveTimerRef.current) {
        clearTimeout(viewportSaveTimerRef.current);
        viewportSaveTimerRef.current = null;
      }

      // 同步期间不保存，防止旧数据覆盖
      if (isSyncingRef.current) {
        return;
      }

      const workspaceService = WorkspaceService.getInstance();
      const currentBoard = workspaceService.getCurrentBoard();
      const latestSnapshot = latestBoardDataRef.current;
      const viewport = latestViewportRef.current;
      const boardId = currentBoardIdRef.current;

      if (
        currentBoard &&
        boardId &&
        (!latestSnapshot || latestSnapshot.boardId !== boardId)
      ) {
        updateLatestBoardData(
          currentBoard.id,
          {
            children: currentBoard.elements,
            viewport: viewport ?? currentBoard.viewport,
            theme: currentBoard.theme,
          },
          Date.now()
        );
      }

      if (reason === 'visibilitychange' && !localDirtyRef.current) {
        return;
      }

      persistCloseSnapshot(reason);
    };

    const handleBeforeUnload = () => {
      flushBoardBeforeLeave('beforeunload');
    };

    // 页面隐藏时也保存（处理移动端和标签页切换）
    const handleVisibilityChange = () => {
      if (document.visibilityState === 'hidden') {
        flushBoardBeforeLeave('visibilitychange');
      }
    };

    const handlePageHide = () => {
      flushBoardBeforeLeave('pagehide');
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    window.addEventListener('pagehide', handlePageHide);
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload);
      window.removeEventListener('pagehide', handlePageHide);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      // 清理定时器
      if (viewportSaveTimerRef.current) {
        clearTimeout(viewportSaveTimerRef.current);
      }
    };
  }, [persistCloseSnapshot, updateLatestBoardData]);

  // 处理安全模式选择
  const handleSafeModeChoice = useCallback((useSafeMode: boolean) => {
    setShowCrashDialog(false);
    if (useSafeMode) {
      crashRecoveryService.enableSafeMode();
    } else {
      crashRecoveryService.clearCrashState();
    }
    // 重新初始化
    setIsLoading(true);
    appInitialized = false;
    // 使用 setTimeout 确保状态更新后再触发 useEffect
    setTimeout(() => {
      void safeReload();
    }, 100);
  }, []);

  // 显示崩溃恢复对话框（统一使用 ErrorFallbackUI）
  if (showCrashDialog) {
    return (
      <ErrorFallbackUI
        variant="crash"
        crashCount={crashRecoveryService.getCrashCount()}
        memoryInfo={crashRecoveryService.getMemoryInfo()}
        onIgnore={() => handleSafeModeChoice(false)}
        onSafeModeReload={() => handleSafeModeChoice(true)}
        onGoToDebug={goToDebug}
      />
    );
  }

  // 初始化失败：展示错误 UI 而非白屏
  if (initError) {
    return (
      <ErrorFallbackUI
        variant="error"
        title="应用初始化失败"
        description="无法加载画板数据，可能是存储损坏或浏览器限制。"
        errorMessage={initError.message}
        errorStack={initError.stack}
        onExportLog={() => collectAndDownloadErrorLog(initError)}
        onSafeModeReload={safeModeReload}
        onGoToDebug={goToDebug}
      />
    );
  }

  if (isLoading) {
    return (
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100vh',
        }}
      >
        加载中...
      </div>
    );
  }

  const hasBoard = new URLSearchParams(appLocation.search).has(BOARD_URL_PARAM);

  if (isCreativeCenterPath(appLocation.pathname) && !hasBoard) {
    const centerParams = new URLSearchParams(appLocation.search);
    return (
      <CreativeCenterPage
        isCreating={isStartingWorkspace}
        onCreateBoard={handleStartCreating}
        onOpenBoard={handleOpenBoardFromCenter}
        onGoHome={handleGoHome}
        onLogin={() => {
          window.location.assign('/account?next=/creative-center');
        }}
        onOpenWorks={handleOpenWorks}
        onOpenWorkflows={handleOpenWorkflows}
        onOpenMusicStation={handleOpenMusicStation}
        onOpenModels={handleOpenModels}
        onOpenTemplates={handleOpenTemplates}
        selectedModelId={centerParams.get('model')}
        selectedMode={centerParams.get('mode')}
      />
    );
  }

  if (isMusicStationPath(appLocation.pathname) && !hasBoard) {
    return (
      <Suspense fallback={null}>
        <MusicStationPage
          onGoHome={handleGoHome}
          onGoCreativeCenter={handleOpenCreativeCenter}
          onOpenAccount={() => handleOpenAccount('/music-station')}
        />
      </Suspense>
    );
  }

  if (isWorksPath(appLocation.pathname) && !hasBoard) {
    return (
      <Suspense fallback={null}>
        <WorksPage
          onGoHome={handleGoHome}
          onGoCreativeCenter={handleOpenCreativeCenterRequest}
          onOpenWorkflows={handleOpenWorkflows}
          onOpenBoard={handleOpenBoardFromCenter}
          onOpenAccount={() => handleOpenAccount('/works')}
        />
      </Suspense>
    );
  }

  if (isWorkflowsPath(appLocation.pathname) && !hasBoard) {
    return (
      <Suspense fallback={null}>
        <WorkflowsPage
          onGoHome={handleGoHome}
          onGoCreativeCenter={handleOpenCreativeCenterRequest}
          onOpenWorks={handleOpenWorks}
          onOpenAccount={() => handleOpenAccount('/workflows')}
        />
      </Suspense>
    );
  }

  if (isProviderAdminPath(appLocation.pathname) && !hasBoard) {
    return (
      <Suspense fallback={null}>
        <ProviderAdminPage onGoHome={handleGoHome} />
      </Suspense>
    );
  }

  if (!hasBoard) {
      return (
        <HomePage
          onStartCreating={handleOpenCreativeCenterRequest}
          onLogin={() => {
            window.location.assign('/account');
          }}
        onOpenMusicStation={handleOpenMusicStation}
        onOpenModel={handleOpenModel}
        onOpenWorks={handleOpenWorks}
        onOpenWorkflows={handleOpenWorkflows}
      />
    );
  }

  const currentBoard = WorkspaceService.getInstance().getCurrentBoard();

  return (
    <WorkspaceShell
      boardName={currentBoard?.name || '未命名创作空间'}
      boardId={currentBoardId}
      elementCount={value.children.length}
      isReady={isDataReady}
      onCreateBoard={handleCreateBoard}
      onSwitchBoard={handleSwitchBoardById}
      onRenameBoard={handleRenameBoard}
      onOpenWorkflows={handleOpenWorkflows}
      onOpenAccount={() => handleOpenAccount(`${window.location.pathname}${window.location.search}`)}
    >
      <Suspense fallback={null}>
        <Drawnix
          value={value.children}
          viewport={value.viewport}
          theme={value.theme}
          onChange={handleBoardChange}
          onViewportChange={handleViewportChange}
          onBoardSwitch={handleBoardSwitch}
          onTabSyncNeeded={handleTabSyncNeeded}
          isDataReady={isDataReady}
          currentBoardId={currentBoardId}
          afterInit={(board) => {
            // 保存 board 引用，用于手动触发边界更新
            boardRef.current = board;
            prefillPendingCreation(getBoardIdFromUrl());

            (
              window as unknown as {
                __drawnix__web__console: (value: string) => void;
              }
            )['__drawnix__web__console'] = (value: string) => {
              addDebugLog(board, value);
            };
          }}
        />
      </Suspense>
    </WorkspaceShell>
  );
}

const addDebugLog = async (board: PlaitBoard, value: string) => {
  const { PlaitBoard } = await import('@plait/core');
  const container = PlaitBoard.getBoardContainer(board).closest(
    '.drawnix'
  ) as HTMLElement | null;
  if (!container) {
    return;
  }
  let consoleContainer = container.querySelector('.drawnix-console');
  if (!consoleContainer) {
    consoleContainer = document.createElement('div');
    consoleContainer.classList.add('drawnix-console');
    container.append(consoleContainer);
  }
  const div = document.createElement('div');
  div.textContent = value;
  consoleContainer.append(div);
};

/**
 * 迁移元素数组中的视频 URL 格式
 * 新格式 (/__aitu_cache__/video/...) 是稳定的，由 Service Worker 直接从 Cache API 返回
 * 旧格式 (blob:...#merged-video-xxx) 需要迁移到新格式
 */
async function recoverVideoUrlsInElements(
  elements: PlaitElement[]
): Promise<PlaitElement[]> {
  return elements.map((element) => {
    const url = (element as any).url as string | undefined;

    // 新格式：稳定 URL，无需处理
    if (url?.startsWith('/__aitu_cache__/video/')) {
      return element;
    }

    // 旧格式：blob URL + #merged-video-xxx
    // 提取 taskId，转换为新格式
    if (url?.startsWith('blob:') && url.includes('#merged-video-')) {
      const hashIndex = url.indexOf('#merged-video-');
      if (hashIndex !== -1) {
        const afterHash = url.substring(hashIndex + 1);
        const nextHashIndex = afterHash.indexOf('#', 1);
        const taskId =
          nextHashIndex > 0 ? afterHash.substring(0, nextHashIndex) : afterHash;

        // 转换为新格式的稳定 URL（带 .mp4 后缀）
        const newUrl = `/__aitu_cache__/video/${taskId}.mp4`;
        // console.log(`[App] Migrating video URL: ${taskId}`);
        return { ...element, url: newUrl };
      }
    }

    return element;
  });
}

/**
 * 从树结构中找到第一个画板
 */
function findFirstBoard(nodes: TreeNode[]): Board | null {
  for (const node of nodes) {
    if (node.type === 'board') {
      return node.data;
    }
    if (node.type === 'folder' && node.children) {
      const board = findFirstBoard(node.children);
      if (board) return board;
    }
  }
  return null;
}

export default App;

import { StrictMode } from 'react';
import * as ReactDOM from 'react-dom/client';
import App from './app';
import { ErrorBoundary } from './ErrorBoundary';
import { initCrashLogger } from '../crash-logger';
import {
  initWebVitals,
  initPageReport,
  initPreventPinchZoom,
  runDatabaseCleanup,
  storageMigrationService,
  initPromptStorageCache,
  toolbarConfigService,
  memoryMonitorService,
  crashRecoveryService,
  swChannelClient,
  safeReload,
  analytics,
} from '@drawnix/drawnix/runtime';
import { initSWConsoleCapture } from '../utils/sw-console-capture';

const isLocalDev =
  typeof window !== 'undefined' &&
  (window.location.hostname === 'localhost' ||
    window.location.hostname === '127.0.0.1');
const swQueryParam =
  typeof window !== 'undefined'
    ? new URLSearchParams(window.location.search).get('sw')
    : null;
const isServiceWorkerExplicitlyDisabled = swQueryParam === '0';
const hasServiceWorkerSupport =
  typeof navigator !== 'undefined' && 'serviceWorker' in navigator;
const shouldUseServiceWorker =
  hasServiceWorkerSupport && !isLocalDev && !isServiceWorkerExplicitlyDisabled;

// ===== 控制台日志捕获（尽早初始化，确保默认 console 被改写） =====
// 必须在其他业务代码之前执行，否则后续工具（如 rrweb）可能先改写 console 导致捕获失效
if (shouldUseServiceWorker) {
  initSWConsoleCapture();
}

// ===== 崩溃恢复检测 =====
// 必须最先执行，检测上次是否因内存不足等原因崩溃
crashRecoveryService.markLoadingStart();
crashRecoveryService.checkUrlSafeMode();

// ===== 初始化崩溃日志系统 =====
// 必须尽早初始化，以捕获启动阶段的内存状态和错误
initCrashLogger();

const LAZY_CHUNK_RETRY_PARAM = '_lazy_chunk_retry';
const LAZY_CHUNK_RETRY_TS_PARAM = '_t';

interface BootProgressOptions {
  title?: string;
  tip?: string;
  note?: string;
  source?: 'phase' | 'sw';
  progress?: number;
}

interface BootController {
  markReady: () => void;
  markError: (message?: string) => void;
  setProgress?: (progress?: number, options?: BootProgressOptions) => void;
}

declare global {
  interface Window {
    __OPENTU_BOOT__?: BootController;
    __OPENTU_SW_REGISTRATION_PROMISE__?: Promise<ServiceWorkerRegistration | null>;
  }
}

function cleanupLazyChunkRecoveryParams(): void {
  if (typeof window === 'undefined') {
    return;
  }

  const url = new URL(window.location.href);
  if (!url.searchParams.has(LAZY_CHUNK_RETRY_PARAM)) {
    return;
  }

  url.searchParams.delete(LAZY_CHUNK_RETRY_PARAM);
  url.searchParams.delete(LAZY_CHUNK_RETRY_TS_PARAM);

  try {
    window.history.replaceState(window.history.state, '', url.toString());
  } catch {
    // ignore URL cleanup failures and continue booting
  }
}

cleanupLazyChunkRecoveryParams();

function getBootController(): BootController | null {
  return window.__OPENTU_BOOT__ || null;
}

function updateBootStatus(options?: BootProgressOptions): void {
  getBootController()?.setProgress?.(options?.progress, options);
}

interface RuntimeSWVersionState {
  committedVersion: string;
  pendingVersion: string | null;
  pendingReadyAt: number | null;
  upgradeState: 'idle' | 'prewarming' | 'ready' | 'committing';
  swVersion: string;
}

function cleanupDisabledServiceWorker(): void {
  navigator.serviceWorker
    .getRegistration()
    .then((registration) => registration?.unregister())
    .catch((error) => {
      console.warn('[Main] Disabled service worker cleanup failed:', error);
    });
}

function scheduleAfterFirstFrameIdle(
  callback: () => void,
  options: { delay?: number; timeout?: number } = {}
): void {
  if (typeof window === 'undefined') {
    return;
  }

  const { delay = 0, timeout = 2000 } = options;
  const run = () => {
    const idleCallback = (
      window as Window & {
        requestIdleCallback?: (
          cb: () => void,
          opts?: { timeout: number }
        ) => number;
      }
    ).requestIdleCallback;

    if (typeof idleCallback === 'function') {
      idleCallback(callback, { timeout });
      return;
    }

    window.setTimeout(callback, Math.min(timeout, 500));
  };

  const start = () => {
    if (delay > 0) {
      window.setTimeout(run, delay);
      return;
    }
    run();
  };

  window.requestAnimationFrame(() => {
    window.requestAnimationFrame(start);
  });
}

updateBootStatus({
  tip: '正在初始化启动服务...',
  source: 'phase',
  progress: 12,
});

// ===== 立即初始化防止双指缩放 =====
// 必须在任何其他代码之前执行，确保事件监听器最先注册
if (typeof window !== 'undefined') {
  initPreventPinchZoom();

  const initAnalyticsMonitoring = (attempt = 0) => {
    if (analytics.isAnalyticsEnabled()) {
      initPageReport();
      return;
    }

    // Do not keep polling forever when reporting is disabled or blocked.
    if (attempt >= 10) {
      return;
    }
    setTimeout(() => initAnalyticsMonitoring(attempt + 1), 300);
  };

  scheduleAfterFirstFrameIdle(() => initAnalyticsMonitoring(), {
    delay: 0,
    timeout: 1000,
  });

  scheduleAfterFirstFrameIdle(
    () => {
      runDatabaseCleanup().catch((error) => {
        console.warn('[Main] Database cleanup failed:', error);
      });

      storageMigrationService
        .runMigration()
        .then(() => {
          return Promise.all([
            initPromptStorageCache(),
            toolbarConfigService.initializeAsync(),
          ]);
        })
        .catch((error) => {
          console.warn('[Main] Storage migration/init failed:', error);
        });
    },
    {
      delay: 400,
      timeout: 2500,
    }
  );

  scheduleAfterFirstFrameIdle(
    () => {
      memoryMonitorService.start();
      memoryMonitorService.logMemoryStatus();
    },
    {
      delay: 5000,
      timeout: 2500,
    }
  );

  // 统计上报为旁路逻辑：page view 尽早初始化，性能指标继续延迟
  const initMonitoring = (attempt = 0) => {
    if (analytics.isAnalyticsEnabled()) {
      initWebVitals();
      return;
    }

    // Give the deferred Umami script a bounded window to initialize.
    if (attempt >= 10) {
      return;
    }
    setTimeout(() => initMonitoring(attempt + 1), 300);
  };

  scheduleAfterFirstFrameIdle(initMonitoring, {
    delay: 1500,
    timeout: 3000,
  });
}

if (hasServiceWorkerSupport && !shouldUseServiceWorker) {
  cleanupDisabledServiceWorker();
}

// 注册Service Worker来处理CORS问题和PWA功能
if (shouldUseServiceWorker) {
  const isDevelopment = isLocalDev;

  // 等待中的新 Worker
  let pendingWorker: ServiceWorker | null = null;
  // 用户是否已确认升级（只有用户确认后才触发刷新）
  let userConfirmedUpgrade = false;
  let upgradeReloadScheduled = false;
  let lastPendingVersionNotified: string | null = null;

  // Global reference to service worker registration
  let swRegistration: ServiceWorkerRegistration | null = null;

  const notifyUpdateReady = (version: string) => {
    if (lastPendingVersionNotified === version) {
      return;
    }
    lastPendingVersionNotified = version;
    window.dispatchEvent(
      new CustomEvent('sw-update-available', {
        detail: { version },
      })
    );
  };

  const handleRuntimeVersionState = (state: RuntimeSWVersionState) => {
    if (
      state.pendingVersion &&
      state.pendingVersion !== state.committedVersion &&
      (state.upgradeState === 'ready' || state.upgradeState === 'committing')
    ) {
      notifyUpdateReady(state.pendingVersion);
      return;
    }

    if (!state.pendingVersion) {
      lastPendingVersionNotified = null;
    }
  };

  const requestSWVersionState = (target?: ServiceWorker | null) => {
    const worker =
      target ||
      pendingWorker ||
      swRegistration?.waiting ||
      navigator.serviceWorker.controller ||
      swRegistration?.active ||
      null;

    if (!worker) {
      return;
    }

    worker.postMessage({ type: 'GET_VERSION_STATE' });
  };

  const claimCurrentClientIfNeeded = (
    registration?: ServiceWorkerRegistration | null
  ) => {
    if (navigator.serviceWorker.controller || !registration?.active) {
      return;
    }

    registration.active.postMessage({ type: 'CLAIM_CLIENTS' });
  };

  const scheduleConfirmedUpgradeReload = (reason: string) => {
    if (!userConfirmedUpgrade || upgradeReloadScheduled) {
      return;
    }

    upgradeReloadScheduled = true;
    // 延迟一点，给新 SW 留出接管后收尾时间
    setTimeout(() => {
      void safeReload();
    }, 1000);
  };

  const resolvePendingUpgradeWorker =
    async (): Promise<ServiceWorker | null> => {
      const candidates: Array<ServiceWorker | null | undefined> = [
        pendingWorker,
        swRegistration?.waiting,
      ];

      try {
        const liveRegistration =
          (await navigator.serviceWorker.getRegistration()) || null;
        if (liveRegistration) {
          swRegistration = liveRegistration;
          candidates.push(liveRegistration.waiting);
        }
      } catch (error) {
        console.warn(
          '[Main] Failed to get live service worker registration:',
          error
        );
      }

      try {
        const readyRegistration = await navigator.serviceWorker.ready;
        candidates.push(readyRegistration.waiting);
      } catch (error) {
        console.warn(
          '[Main] Failed to inspect ready service worker registration:',
          error
        );
      }

      for (const worker of candidates) {
        if (!worker || worker.state === 'redundant') {
          continue;
        }

        // staged update only commits the waiting/installed worker, never the old controller
        if (worker === navigator.serviceWorker.controller) {
          continue;
        }

        pendingWorker = worker;
        return worker;
      }

      return null;
    };

  const swRegistrationPromise =
    window.__OPENTU_SW_REGISTRATION_PROMISE__ ||
    navigator.serviceWorker.register('/sw.js').catch((error) => {
      console.warn('[Main] Service worker registration failed:', error);
      return null;
    });

  window.__OPENTU_SW_REGISTRATION_PROMISE__ = swRegistrationPromise;

  swRegistrationPromise
    .then((registration) => {
      if (!registration) {
        updateBootStatus({
          tip: '离线加速未启用，正在直接启动工作台...',
          source: 'phase',
          progress: 70,
        });
        return;
      }

      swRegistration = registration;
      claimCurrentClientIfNeeded(registration);
      navigator.serviceWorker.ready
        .then(claimCurrentClientIfNeeded)
        .catch((error) => {
          console.warn('[Main] Service worker ready check failed:', error);
        });
      updateBootStatus({
        tip: '启动缓存服务已连接，正在准备资源清单...',
        source: 'phase',
        progress: 72,
      });

      // 在开发模式下，强制检查更新并处理等待中的Worker
      if (isDevelopment) {
        registration
          .update()
          .catch((err) => console.warn('Forced update check failed:', err));

        if (registration.waiting) {
          registration.waiting.postMessage({ type: 'FORCE_UPGRADE' });
        }
      } else if (registration.waiting && navigator.serviceWorker.controller) {
        pendingWorker = registration.waiting;
        requestSWVersionState(registration.waiting);
      }

      // 监听Service Worker更新
      registration.addEventListener('updatefound', () => {
        const newWorker = registration.installing;
        if (newWorker) {
          newWorker.addEventListener('statechange', () => {
            if (
              newWorker.state === 'installed' &&
              navigator.serviceWorker.controller
            ) {
              pendingWorker = newWorker;

              // 在开发模式下自动激活新的Service Worker
              if (isDevelopment) {
                newWorker.postMessage({ type: 'FORCE_UPGRADE' });
              } else {
                requestSWVersionState(newWorker);
                // 重试：覆盖 SW 仍在预缓存、首次响应丢失的情况
                setTimeout(() => requestSWVersionState(newWorker), 5000);
              }
            }
          });
        }
      });

      if (
        registration.active &&
        !registration.installing &&
        !registration.waiting
      ) {
        updateBootStatus({
          tip: '启动缓存服务已就绪，正在恢复工作台状态...',
          source: 'phase',
          progress: 78,
        });
      }

      requestSWVersionState();

      // 定期检查更新（每 5 分钟检查一次）
      setInterval(() => {
        registration.update().catch((error) => {
          console.warn('Update check failed:', error);
        });
      }, 5 * 60 * 1000);

      // 页面重新可见时检查版本状态，捕获 tab 切走期间错过的升级通知
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') {
          requestSWVersionState();
        }
      });
    })
    .catch((error) => {
      updateBootStatus({
        tip: '离线加速未启用，正在直接启动工作台...',
        source: 'phase',
        progress: 70,
      });
    });

  // 设置 SW 事件处理器（通过 postmessage-duplex）
  const setupSWEventHandlers = () => {
    if (!swChannelClient.isInitialized()) {
      setTimeout(setupSWEventHandlers, 500);
      return;
    }

    swChannelClient.setEventHandlers({
      onSWUpdated: (_event) => {
        // sw:updated 在 skipWaiting() 后立即发出，早于 activate/claim。
        // 这里只同步一次状态，真正刷新等待 sw:activated / controllerchange。
        requestSWVersionState();
      },
      onSWNewVersionReady: (event) => {
        notifyUpdateReady(event.version);
        requestSWVersionState();
      },
      onSWActivated: (_event) => {
        if (userConfirmedUpgrade) {
          scheduleConfirmedUpgradeReload('sw:activated');
          return;
        }

        // 老版本页面关闭后，waiting worker 可能在后台自然转为 active。
        // 这时不再重复弹升级提示，只更新运行时状态。
        pendingWorker = null;
        requestSWVersionState();
      },
    });

    if (swRegistration?.waiting && navigator.serviceWorker.controller) {
      pendingWorker = swRegistration.waiting;
      requestSWVersionState(swRegistration.waiting);
    }
  };

  // 延迟初始化 SW 事件处理器，等待 swChannelClient 就绪
  setTimeout(setupSWEventHandlers, 1000);

  // 注册视频缩略图生成处理器（使用 postmessage-duplex 双工通讯）
  // SW 通过 publish('thumbnail:generate', { url }) 请求，主线程处理并直接返回结果
  const setupVideoThumbnailHandler = async () => {
    // 等待 swChannelClient 初始化
    if (!swChannelClient.isInitialized()) {
      setTimeout(setupVideoThumbnailHandler, 500);
      return;
    }

    swChannelClient.registerVideoThumbnailHandler(async (url, maxSize) => {
      try {
        const { generateVideoThumbnailFromBlob } = await import('@aitu/utils');

        let videoBlob: Blob | null = null;

        // 1. 尝试从缓存获取视频 blob
        const cache = await caches.open('drawnix-images');
        const cachedResponse = await cache.match(url);
        if (cachedResponse) {
          videoBlob = await cachedResponse.blob();
        }

        // 2. 如果缓存中没有，尝试从网络获取（支持远程视频）
        if (
          !videoBlob &&
          (url.startsWith('http://') || url.startsWith('https://'))
        ) {
          try {
            const networkResponse = await fetch(url);
            if (networkResponse.ok) {
              videoBlob = await networkResponse.blob();
            }
          } catch {
            videoBlob = null;
          }
        }

        if (!videoBlob) {
          return { error: 'Video not found in cache or network' };
        }

        // 生成预览图
        const thumbnailBlob = await generateVideoThumbnailFromBlob(
          videoBlob,
          maxSize || 400
        );

        // 将 Blob 转换为 Data URL
        const thumbnailUrl = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.onerror = reject;
          reader.readAsDataURL(thumbnailBlob);
        });

        return { thumbnailUrl };
      } catch (error) {
        return {
          error: error instanceof Error ? error.message : String(error),
        };
      }
    });
  };

  setupVideoThumbnailHandler();

  navigator.serviceWorker.addEventListener('message', (event: MessageEvent) => {
    if (event.data?.type === 'SW_VERSION_STATE') {
      handleRuntimeVersionState(event.data as RuntimeSWVersionState);
    }
  });

  // 监听controller变化（新的Service Worker接管）
  // 只有用户主动确认升级后才刷新页面
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    requestSWVersionState();
    scheduleConfirmedUpgradeReload('controllerchange');
  });

  // 监听用户确认升级事件
  window.addEventListener('user-confirmed-upgrade', () => {
    void (async () => {
      const worker = await resolvePendingUpgradeWorker();
      if (!worker) {
        console.warn(
          '[Main] No waiting service worker available for COMMIT_UPGRADE'
        );
        requestSWVersionState();
        swRegistration?.update().catch((error) => {
          console.warn(
            '[Main] Update check after missing waiting worker failed:',
            error
          );
        });
        return;
      }

      // 标记用户已确认升级，允许后续的 reload
      userConfirmedUpgrade = true;
      worker.postMessage({ type: 'COMMIT_UPGRADE' });
    })();
  });

  // 页面卸载前，不再自动触发升级，必须用户手动确认
  // window.addEventListener('beforeunload', () => {
  //   if (newVersionReady && pendingWorker) {
  //     console.log('Main: Page unloading, triggering pending upgrade');
  //     pendingWorker.postMessage({ type: 'SKIP_WAITING' });
  //   }
  // });

  // 页面隐藏时，不再自动触发升级
  // document.addEventListener('visibilitychange', () => {
