// 估算 videoBlobCache 的总大小（字节）
function estimateVideoBlobCacheSize(): number {
  let totalSize = 0;
  videoBlobCache.forEach((entry) => {
    if (entry.blob) {
      totalSize += entry.blob.size;
    }
  });
  return totalSize;
}

