    limit?: number;
    offset?: number;
    filter?: Record<string, unknown>;
  }): Promise<{
    logs: unknown[];
    total: number;
    offset: number;
    limit: number;
    stats?: Record<string, unknown>;
  }> {
    try {
      const { getAllLogs, getLogStats } = await import('./postmessage-logger');
      const { limit = 200, offset = 0, filter } = data || {};
      let logs = getAllLogs();

      // Apply filters
      if (filter) {
        if (filter.direction) {
          logs = logs.filter((l) => l.direction === filter.direction);
        }
        if (filter.messageType) {
          const search = (filter.messageType as string).toLowerCase();
          logs = logs.filter((l) =>
            l.messageType?.toLowerCase().includes(search)
          );
        }
      }

      const paginatedLogs = logs.slice(offset, offset + limit);
      return {
        logs: paginatedLogs,
        total: logs.length,
        offset,
        limit,
        stats: getLogStats(),
      };
    } catch {
      return {
        logs: [],
        total: 0,
        offset: data?.offset || 0,
        limit: data?.limit || 200,
      };
    }
