/**
 * Debug Fetch Wrapper for Service Worker Internal Requests
 * 
 * Since SW internal fetch() calls don't trigger the SW's fetch event,
 * we need to manually log them for debugging purposes.
 */

import { sanitizeRequestBody } from './utils/sanitize-utils';

interface FormDataField {
  name: string;
  value: string;
  isFile?: boolean;
  fileName?: string;
  mimeType?: string;
  dataUrl?: string; // Base64 data URL for images
}

interface Base64Image {
  key: string;
  dataUrl: string;
  mimeType: string;
  size: number; // Size in KB
}

interface DebugFetchLog {
  id: string;
  timestamp: number;
  url: string;
  method: string;
  requestType: 'sw-internal';
  status?: number;
  statusText?: string;
  duration?: number;
  error?: string;
  details?: string;
  requestBody?: string;
  responseBody?: string;
  formData?: FormDataField[]; // Parsed FormData fields
  base64Images?: Base64Image[]; // Extracted base64 images from request body
  isStreaming?: boolean; // Whether this is a streaming response
}

// Store for internal fetch logs
const internalFetchLogs: DebugFetchLog[] = [];
const MAX_INTERNAL_LOGS = 100;

// Debug mode enabled flag (synced with main SW)
let debugModeEnabled = false;

// Callback for broadcasting logs
let broadcastCallback: ((log: DebugFetchLog) => void) | null = null;

/**
 * Enable or disable debug mode for debugFetch
 * Should be synced with main SW debug mode
 */
export function setDebugFetchEnabled(enabled: boolean) {
  debugModeEnabled = enabled;
}

/**
 * Check if debug fetch is enabled
 */
export function isDebugFetchEnabled(): boolean {
  return debugModeEnabled;
}

/**
 * Set the broadcast callback for sending logs to debug panel
 */
export function setDebugFetchBroadcast(callback: (log: DebugFetchLog) => void) {
  broadcastCallback = callback;
}

/**
 * Get all internal fetch logs
 */
export function getInternalFetchLogs(): DebugFetchLog[] {
  return [...internalFetchLogs];
}

/**
 * Clear internal fetch logs
 */
export function clearInternalFetchLogs() {
  internalFetchLogs.length = 0;
}

/**
 * Update an existing log's response body (for streaming responses)
 * @param logId - The ID of the log to update
 * @param responseBody - The final response body content
 */
export function updateLogResponseBody(logId: string, responseBody: string) {
  const log = internalFetchLogs.find(l => l.id === logId);
  if (log) {
    // Truncate if too long
    log.responseBody = responseBody.length > 5000 
      ? responseBody.substring(0, 5000) + '...(truncated)' 
      : responseBody;
    
    // Broadcast updated log
    if (broadcastCallback) {
      broadcastCallback({ ...log });
    }
  }
}

/**
 * Convert Blob to base64 data URL
 */
async function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

/**
 * Parse FormData into an array of fields
 */
async function parseFormData(formData: FormData): Promise<FormDataField[]> {
  const fields: FormDataField[] = [];
  
  for (const [name, value] of (formData as any).entries()) {
    if (value instanceof Blob) {
      const field: FormDataField = {
        name,
        value: `[${value.type || 'binary'}] ${value.size} bytes`,
        isFile: true,
        mimeType: value.type,
      };
      
      // For images, convert to data URL for preview
      if (value.type.startsWith('image/') && value.size < 5 * 1024 * 1024) {
        try {
          field.dataUrl = await blobToDataUrl(value);
        } catch {
          // Ignore conversion errors
        }
      }
      
      if (value instanceof File) {
        field.fileName = value.name;
      }
      
      fields.push(field);
    } else {
      fields.push({
        name,
        value: String(value).length > 500 
          ? String(value).substring(0, 500) + '...' 
          : String(value),
      });
    }
  }
  
  return fields;
}

// Extended Response type with debug log ID
export interface DebugResponse extends Response {
  __debugLogId?: string;
}

/**
 * Wrapper for fetch that logs API calls
 * Use this for important API calls that need to be visible in debug panel
 * 
 * For streaming responses, you can update the final response body using:
 * updateLogResponseBody(response.__debugLogId, finalContent)
 */
export async function debugFetch(
  input: RequestInfo | URL,
  init?: RequestInit,
  options?: {
    label?: string;
    logRequestBody?: boolean;
    logResponseBody?: boolean;
    isStreaming?: boolean; // Mark as streaming response (SSE, etc.)
  }
): Promise<DebugResponse> {
  // Skip all debug processing if debug mode is disabled - zero overhead
  if (!debugModeEnabled) {
    return fetch(input, init) as Promise<DebugResponse>;
  }
  
  const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
  const method = init?.method || 'GET';
  const startTime = Date.now();
  const id = Math.random().toString(36).substring(2, 10);
  
  // Parse request body for logging
  let requestBody: string | undefined;
  let formData: FormDataField[] | undefined;
  let base64Images: Base64Image[] | undefined;
  
  if (init?.body) {
    if (init.body instanceof FormData) {
      // Parse FormData with image support
      try {
        formData = await parseFormData(init.body);
      } catch {
        requestBody = '[FormData - unable to parse]';
      }
    } else if (options?.logRequestBody) {
      try {
        const bodyStr = typeof init.body === 'string' 
          ? init.body 
          : JSON.stringify(init.body);
        
        // Extract base64 images BEFORE truncating
        const imageRegex = /data:image\/([^;]+);base64,([A-Za-z0-9+/=]+)/g;
        let match;
        let imageIndex = 0;
        base64Images = [];
        
        while ((match = imageRegex.exec(bodyStr)) !== null) {
          const mimeType = `image/${match[1]}`;
          const base64Data = match[2];
          // Only include substantial images (at least 1KB of data)
          if (base64Data.length > 1000) {
            base64Images.push({
              key: `image[${imageIndex}]`,
              dataUrl: `data:${mimeType};base64,${base64Data}`,
              mimeType,
              size: Math.round(base64Data.length * 0.75 / 1024)
            });
            imageIndex++;
          }
        }
        
        if (base64Images.length === 0) {
          base64Images = undefined;
        }
        
        // Truncate display body (replace base64 with placeholder for display)
        let displayBody = bodyStr.replace(
          /data:image\/([^;]+);base64,[A-Za-z0-9+/=]+/g,
          (_, mimeType) => `[📷 image/${mimeType}]`
        );
        
        // 对请求体进行脱敏处理，过滤 API Key 等敏感信息
        displayBody = sanitizeRequestBody(displayBody);
        
        // 对于 chat/completions 接口，不截断请求体（用于调试和成本追踪）
        const isChatEndpoint = url.includes('/chat/completions');
        requestBody = !isChatEndpoint && displayBody.length > 3000 
          ? displayBody.substring(0, 3000) + '...(truncated)' 
          : displayBody;
      } catch {
        requestBody = '[unable to serialize body]';
      }
    }
  }
  
  const log: DebugFetchLog = {
    id,
    timestamp: startTime,
    url,
    method,
    requestType: 'sw-internal',
    details: options?.label || `SW Internal: ${method} ${new URL(url).pathname}`,
    requestBody,
    formData,
    base64Images,
    isStreaming: options?.isStreaming,
  };
  
  // Add to logs
  internalFetchLogs.unshift(log);
  if (internalFetchLogs.length > MAX_INTERNAL_LOGS) {
    internalFetchLogs.pop();
  }
  
  // Broadcast initial log
  if (broadcastCallback) {
    broadcastCallback({ ...log });
  }
  
  try {
    const response = await fetch(input, init);
    
    // Update log with response info
    log.status = response.status;
    log.statusText = response.statusText;
    log.duration = Date.now() - startTime;
    
    // Log response body if requested (skip for streaming responses)
    if (options?.isStreaming) {
      // Mark as streaming - can't capture response body
      log.responseBody = '[流式响应 - 数据通过 SSE/Stream 实时传输，无法捕获完整响应体]';
    } else if (options?.logResponseBody) {
      try {
        const contentType = response.headers.get('content-type') || '';
        if (contentType.includes('application/json') || contentType.includes('text/')) {
          const clone = response.clone();
          const text = await clone.text();
          log.responseBody = text.length > 2000 
            ? text.substring(0, 2000) + '...(truncated)' 
            : text;
        }
      } catch {
        // Ignore response body read errors
      }
    }
    
    // Broadcast updated log
    if (broadcastCallback) {
      broadcastCallback({ ...log });
    }
    
    // Attach log ID to response for later updates (e.g., streaming final content)
    (response as DebugResponse).__debugLogId = id;
    
    return response as DebugResponse;
  } catch (error: any) {
    const errorMessage = error.message || String(error);
    
    // Parse network error type for better display
    let errorType = 'NETWORK_ERROR';
    if (errorMessage.includes('ERR_CONNECTION_CLOSED')) {
      errorType = 'ERR_CONNECTION_CLOSED';
    } else if (errorMessage.includes('ERR_CONNECTION_REFUSED')) {
      errorType = 'ERR_CONNECTION_REFUSED';
    } else if (errorMessage.includes('ERR_CONNECTION_RESET')) {
      errorType = 'ERR_CONNECTION_RESET';
    } else if (errorMessage.includes('ERR_CONNECTION_TIMED_OUT') || errorMessage.includes('timeout')) {
      errorType = 'ERR_TIMEOUT';
    } else if (errorMessage.includes('ERR_NAME_NOT_RESOLVED')) {
      errorType = 'ERR_DNS_FAILED';
    } else if (errorMessage.includes('ERR_INTERNET_DISCONNECTED')) {
      errorType = 'ERR_OFFLINE';
    } else if (errorMessage.includes('ERR_SSL') || errorMessage.includes('certificate')) {
      errorType = 'ERR_SSL';
    } else if (errorMessage.includes('Failed to fetch')) {
      errorType = 'FETCH_FAILED';
    } else if (errorMessage.includes('AbortError') || errorMessage.includes('aborted')) {
      errorType = 'ABORTED';
    }
    
    log.status = 0; // Use 0 to indicate network error (no HTTP response)
    log.statusText = errorType;
    log.error = errorMessage;
    log.duration = Date.now() - startTime;
    
    // Broadcast error log
    if (broadcastCallback) {
      broadcastCallback({ ...log });
    }
    
    throw error;
  }
}

/**
 * PostMessage Logger for Service Worker
 *
 * 记录主线程与Service Worker之间的所有消息通讯
 * 用于调试面板的PostMessage日志功能
 *
 * 注意：只有在调试模式启用时才会记录日志，避免影响性能。
 * PostMessage 日志记录完全由调试模式控制，不会对未开启调试模式的应用性能产生影响。
 */

import { sanitizeObject as sanitizeObjectFromUtils } from '@aitu/utils';

// 调试模式开关（默认关闭，避免影响性能）
let debugModeEnabled = false;

// 日志存储（保留最近500条）
const MAX_LOGS = 500;
const logs: PostMessageLogEntry[] = [];

// 消息ID计数器
let logIdCounter = 0;

/**
 * 内部标志：检查是否真的已启用调试模式
 * 用于防止调试面板自身的消息被记录
 */
function isDebugModeActive(): boolean {
  return debugModeEnabled;
}

export interface PostMessageLogEntry {
  id: string;
  timestamp: number;
  direction: 'send' | 'receive';
  messageType: string;
  data?: unknown;
  response?: unknown;
  error?: string;
  clientId?: string;
  clientUrl?: string;
  clientType?: 'main' | 'debug' | 'other'; // 区分应用页面、调试面板、其他
  duration?: number;
}

// 排除的消息类型（调试面板自身的消息）
// 包括 native message types 和 postmessage-duplex event names
const EXCLUDED_MESSAGE_TYPES = [
  // Native message types
  'SW_DEBUG_ENABLE',
  'SW_DEBUG_DISABLE',
  'SW_DEBUG_GET_STATUS',
  'SW_DEBUG_CLEAR_LOGS',
  'SW_DEBUG_CLEAR_CONSOLE_LOGS',
  'SW_DEBUG_GET_CONSOLE_LOGS',
  'SW_DEBUG_EXPORT_LOGS',
  'SW_DEBUG_HEARTBEAT',
  'SW_DEBUG_STATUS',
  'SW_DEBUG_ENABLED',
  'SW_DEBUG_DISABLED',
  'SW_DEBUG_LOG',
  'SW_DEBUG_LOGS',
  'SW_DEBUG_LOGS_CLEARED',
  'SW_CONSOLE_LOG',
  'SW_DEBUG_CONSOLE_LOGS',
  'SW_DEBUG_CONSOLE_LOGS_CLEARED',
  'SW_POSTMESSAGE_LOG',
  'SW_DEBUG_POSTMESSAGE_LOGS',
  'SW_DEBUG_POSTMESSAGE_LOGS_CLEARED',
  'SW_DEBUG_NEW_CRASH_SNAPSHOT',
  'SW_DEBUG_CRASH_SNAPSHOTS',
  'SW_DEBUG_CRASH_SNAPSHOTS_CLEARED',
  'SW_DEBUG_GET_CRASH_SNAPSHOTS',
  'SW_DEBUG_CLEAR_CRASH_SNAPSHOTS',
  'CRASH_SNAPSHOT',
  // postmessage-duplex debug event names (避免死循环)
  'debug:log',
  'debug:llmLog',
  'debug:statusChanged',
  'debug:enable',
  'debug:disable',
  'debug:getStatus',
  'debug:getLogs',
  'debug:clearLogs',
  'debug:getConsoleLogs',
  'debug:clearConsoleLogs',
  'debug:getPostMessageLogs',
  'debug:clearPostMessageLogs',
  'debug:getCrashSnapshots',
  'debug:clearCrashSnapshots',
  'debug:getLLMApiLogs',
  'debug:clearLLMApiLogs',
  'debug:getCacheStats',
  'debug:exportLogs',
  'debug:newCrashSnapshot',
  'console:log',
  'console:report',
  'postmessage:log',
  'postmessage:logBatch',
  'crash:snapshot',
  'crash:heartbeat',
];

// 请求-响应关联映射
const pendingRequests = new Map<string, {
  entry: PostMessageLogEntry;
  startTime: number;
}>();

/**
 * 设置调试模式
 * 只有调试模式启用时才记录日志
 */
export function setPostMessageLoggerDebugMode(enabled: boolean): void {
  const wasEnabled = debugModeEnabled;
  debugModeEnabled = enabled;
  
  if (!enabled && wasEnabled) {
    // 从启用变为禁用时，立即清空日志，释放内存
    logs.length = 0;
    pendingRequests.clear();
    logIdCounter = 0;
  }
}

/**
 * 检查调试模式是否启用
 */
export function isPostMessageLoggerDebugMode(): boolean {
  return debugModeEnabled;
}

/**
 * 检查消息是否应该被记录
 * 只有调试模式启用且消息类型不在排除列表中时才记录
 */
function shouldLogMessage(messageType: string): boolean {
  // 调试模式未启用时，立即返回 false，不进行任何记录操作
  if (!isDebugModeActive()) {
    return false;
  }
  
  // 过滤掉 unknown 类型的消息（通常是 postmessage-duplex 的内部响应）
  if (messageType === 'unknown') {
    return false;
  }
  
  // 直接匹配排除列表
  if (EXCLUDED_MESSAGE_TYPES.includes(messageType)) {
    return false;
  }
  
  // 处理 RPC 格式的消息: RPC:xxx 或 RPC:xxx:response 或 RPC:xxx:error
  // 提取实际的方法名（去掉 RPC: 前缀和 :response/:error 后缀）
  if (messageType.startsWith('RPC:')) {
    let methodName = messageType.slice(4); // 去掉 "RPC:" 前缀
    if (methodName.endsWith(':response')) {
      methodName = methodName.slice(0, -9);
    } else if (methodName.endsWith(':error')) {
      methodName = methodName.slice(0, -6);
    }
    // 检查方法名是否在排除列表中
    if (EXCLUDED_MESSAGE_TYPES.includes(methodName)) {
      return false;
    }
  }
  
  return true;
}

/**
 * 获取客户端类型和 URL（用于在 SW 环境中识别应用页面）
 * @returns {object} { type: 'main' | 'debug' | 'other', url?: string }
 */
function getClientInfo(clientUrl?: string): { clientType?: string; clientUrl?: string } {
  if (!clientUrl) {
    return {};
  }

  let clientType: 'main' | 'debug' | 'other' = 'other';

  // 判断客户端类型
  if (clientUrl.includes('sw-debug')) {
    clientType = 'debug';
  } else if (clientUrl.includes('localhost') || clientUrl.includes('127.0.0.1')) {
    clientType = 'main';
  } else if (!clientUrl.includes('chrome-extension') && !clientUrl.includes('moz-extension')) {
    clientType = 'main';
  }

  return {
    clientType,
    clientUrl: new URL(clientUrl).pathname + new URL(clientUrl).search,
  };
}

/**
 * 记录收到的消息
 */
export function logReceivedMessage(
  messageType: string,
  data: unknown,
  clientId?: string,
  clientUrl?: string,
  isInternal?: boolean
): string {
  // 跳过内部消息，防止循环记录
  if (isInternal) {
    return '';
  }

  if (!shouldLogMessage(messageType)) {
    return '';
  }

  const clientInfo = getClientInfo(clientUrl);
  
  // 过滤掉调试面板客户端的消息
  if (clientInfo.clientType === 'debug') {
    return '';
  }
  const logId = `pm-recv-${Date.now()}-${++logIdCounter}`;
  const entry: PostMessageLogEntry = {
    id: logId,
    timestamp: Date.now(),
    direction: 'receive',
    messageType,
    data: sanitizeData(data),
    clientId,
    clientUrl: clientInfo.clientUrl,
    clientType: clientInfo.clientType as any,
  };

  addLog(entry);

  // 如果是请求类消息，记录开始时间
  if (isRequestMessage(messageType)) {
    const requestId = getRequestId(data);
    if (requestId) {
      pendingRequests.set(requestId, {
        entry,
        startTime: Date.now(),
      });
    }
  }

  return logId;
}

/**
 * 记录发送的消息
 */
export function logSentMessage(
  messageType: string,
  data: unknown,
  clientId?: string,
  clientUrl?: string
): string {
  if (!shouldLogMessage(messageType)) {
    return '';
  }

  const clientInfo = getClientInfo(clientUrl);
  
  // 过滤掉发送给调试面板的消息
  if (clientInfo.clientType === 'debug') {
    return '';
  }
  const logId = `pm-send-${Date.now()}-${++logIdCounter}`;
  const entry: PostMessageLogEntry = {
    id: logId,
    timestamp: Date.now(),
    direction: 'send',
    messageType,
    data: sanitizeData(data),
    clientId,
    clientUrl: clientInfo.clientUrl,
    clientType: clientInfo.clientType as any,
  };

  // 关联的请求条目 ID（用于广播更新后的请求）
  let linkedRequestId: string | null = null;

  // 如果是响应类消息，关联请求并计算耗时
  if (isResponseMessage(messageType)) {
    const requestId = getRequestId(data);
    if (requestId) {
      const pending = pendingRequests.get(requestId);
      if (pending) {
        entry.duration = Date.now() - pending.startTime;
        pending.entry.response = sanitizeData(data);
        pending.entry.duration = entry.duration;
        linkedRequestId = pending.entry.id;
        pendingRequests.delete(requestId);
      }
    }
  }

  addLog(entry);
  
  // 返回响应 logId 和关联的请求 logId（如果有）
  // 格式: "responseId|requestId" 或 "responseId"
  return linkedRequestId ? `${logId}|${linkedRequestId}` : logId;
}

/**
 * 添加日志条目
 */
function addLog(entry: PostMessageLogEntry): void {
  logs.unshift(entry);
  if (logs.length > MAX_LOGS) {
    logs.pop();
  }
}

/**
 * 更新请求日志的响应数据（不创建新的日志条目）
 * 用于双工通讯场景，将响应合并到请求日志中显示
 * @returns 更新后的请求日志 ID，如果找不到请求则返回空字符串
 */
export function updateRequestWithResponse(
  requestId: string,
  response: unknown,
  duration: number,
  error?: string
): string {
  if (!isDebugModeActive()) {
    return '';
  }

  const pending = pendingRequests.get(requestId);
  if (pending) {
    pending.entry.response = sanitizeData(response);
    pending.entry.duration = duration;
    if (error) {
      pending.entry.error = error;
    }
    const logId = pending.entry.id;
    pendingRequests.delete(requestId);
    return logId;
  }
  
  return '';
}

/**
 * 获取所有日志
 */
export function getAllLogs(): PostMessageLogEntry[] {
  return [...logs];
}

/**
 * 清空日志
 */
export function clearLogs(): void {
  logs.length = 0;
  pendingRequests.clear();
  logIdCounter = 0;
}

/**
 * 判断是否为请求类消息
 */
function isRequestMessage(messageType: string): boolean {
  // RPC 请求：以 RPC: 开头，但不以 :response 或 :error 结尾
  if (messageType.startsWith('RPC:') && !messageType.endsWith(':response') && !messageType.endsWith(':error')) {
    return true;
  }
  
  const requestPatterns = [
    'TASK_SUBMIT',
    'TASK_CANCEL',
    'TASK_RETRY',
    'TASK_DELETE',
    'TASK_GET_',
    'WORKFLOW_SUBMIT',
    'WORKFLOW_CANCEL',
    'WORKFLOW_GET_',
    'CHAT_START',
    'MCP_TOOL_EXECUTE',
    'MAIN_THREAD_TOOL_REQUEST',
  ];
  return requestPatterns.some(p => messageType.includes(p));
}

/**
 * 判断是否为响应类消息
 */
function isResponseMessage(messageType: string): boolean {
  // RPC 响应：以 :response 或 :error 结尾
  if (messageType.endsWith(':response') || messageType.endsWith(':error')) {
    return true;
  }
  
  const responsePatterns = [
    'TASK_QUEUE_INITIALIZED',
    'TASK_STATUS',
    'TASK_COMPLETED',
    'TASK_FAILED',
    'TASK_CREATED',
    'TASK_CANCELLED',
    'TASK_DELETED',
    'WORKFLOW_STATUS',
    'WORKFLOW_STEP_STATUS',
    'WORKFLOW_COMPLETED',
    'WORKFLOW_FAILED',
    'CHAT_CHUNK',
    'CHAT_DONE',
    'CHAT_ERROR',
    'MCP_TOOL_RESULT',
    'MAIN_THREAD_TOOL_RESPONSE',
  ];
  return responsePatterns.some(p => messageType.includes(p));
}

/**
 * 从消息数据中提取请求ID
 */
function getRequestId(data: unknown): string | null {
  if (!data || typeof data !== 'object') return null;
  const obj = data as Record<string, unknown>;
  return (obj.requestId as string) 
    || (obj.taskId as string) 
    || (obj.workflowId as string) 
    || (obj.chatId as string) 
    || null;
}

/**
 * 清理敏感数据 - 使用 @aitu/utils 的 sanitizeObject
 */
function sanitizeData(data: unknown): unknown {
  if (!data) return data;

  try {
    // 使用 JSON 深拷贝确保可序列化，然后使用 utils 的 sanitize
    const cloned = JSON.parse(JSON.stringify(data));
    return sanitizeObjectFromUtils(cloned);
  } catch {
    // 无法序列化的数据
    return '[Non-serializable data]';
  }
}

/**
 * 获取日志统计信息
 */
export function getLogStats(): {
  total: number;
  sent: number;
  received: number;
  byType: Record<string, number>;
} {
  const stats = {
    total: logs.length,
    sent: 0,
    received: 0,
    byType: {} as Record<string, number>,
  };

  for (const log of logs) {
    if (log.direction === 'send') {
      stats.sent++;
    } else {
      stats.received++;
    }

    if (!stats.byType[log.messageType]) {
      stats.byType[log.messageType] = 0;
    }
    stats.byType[log.messageType]++;
  }

  return stats;
}

/**
 * Service Worker Task Queue Storage
 *
 * Provides IndexedDB-based persistence for task queue state.
 * Ensures tasks survive page refreshes and SW restarts.
 *
 * Supports:
 * - Tasks (image/video/character generation)
 * - Workflows (multi-step operations)
 * - Chat Workflows (LLM chat with tool execution)
 * - Pending Tool Requests (main thread tool delegation)
 */

import type { SWTask, GeminiConfig, VideoAPIConfig, ChatParams } from './types';
import { getSafeErrorMessage } from './utils/sanitize-utils';

// Import Workflow type from the main package's workflow-engine types
import type { Workflow } from '../../../../../packages/drawnix/src/services/workflow-engine/types';

/**
 * Inline ChatWorkflow type (previously imported from deleted chat-workflow/types.ts)
 * Kept for IndexedDB storage compatibility
 */
interface ChatWorkflow {
  id: string;
  status: string;
  params: ChatParams;
  content: string;
  aiAnalysis?: string;
  toolCalls: Array<{
    id: string;
    name: string;
    arguments: Record<string, unknown>;
    status: string;
    result?: {
      success: boolean;
      data?: unknown;
      error?: string;
      taskId?: string;
    };
  }>;
  createdAt: number;
  updatedAt: number;
  completedAt?: number;
  error?: string;
}

/**
 * Task-Step mapping for unified progress sync
 * (Duplicated here to avoid circular dependency with task-step-registry.ts)
 */
export interface TaskStepMapping {
  taskId: string;
  workflowId: string;
  stepId: string;
  createdAt: number;
}

const DB_NAME = 'sw-task-queue';
const MIN_DB_VERSION = 3; // Minimum required version (with task-step mappings store)
const TASKS_STORE = 'tasks';
const CONFIG_STORE = 'config';
const WORKFLOWS_STORE = 'workflows';
const CHAT_WORKFLOWS_STORE = 'chat-workflows';
const PENDING_TOOL_REQUESTS_STORE = 'pending-tool-requests';
const PENDING_DOM_OPERATIONS_STORE = 'pending-dom-operations';
const TASK_STEP_MAPPINGS_STORE = 'task-step-mappings';
const PENDING_CANVAS_OPERATIONS_STORE = 'pending-canvas-operations';

// All required stores for integrity check
const REQUIRED_STORES = [
  TASKS_STORE,
  CONFIG_STORE,
  WORKFLOWS_STORE,
  CHAT_WORKFLOWS_STORE,
  PENDING_TOOL_REQUESTS_STORE,
  PENDING_DOM_OPERATIONS_STORE,
  TASK_STEP_MAPPINGS_STORE,
  PENDING_CANVAS_OPERATIONS_STORE,
];

/**
 * Pending tool request stored in IndexedDB
 */
export interface StoredPendingToolRequest {
  requestId: string;
  workflowId: string;
  stepId: string;
  toolName: string;
  args: Record<string, unknown>;
  createdAt: number;
  /** ID of the client that initiated the request */
  clientId?: string;
}

/**
 * Pending DOM operation stored in IndexedDB
 *
 * When a main-thread tool completes in SW but no client is available,
 * the result is stored here. When a client reconnects, these operations
 * are sent to the client to continue execution.
 */
export interface PendingDomOperation {
  /** Unique operation ID */
  id: string;
  /** Associated workflow ID */
  workflowId: string;
  /** Associated chat ID (for chat workflows) */
  chatId: string;
  /** Tool name that needs to be executed on main thread */
  toolName: string;
  /** Tool arguments */
  toolArgs: Record<string, unknown>;
  /** Result from SW tool execution (e.g., generated image URL) */
  toolResult: unknown;
  /** Tool call ID (for tracking in workflow) */
  toolCallId: string;
  /** Creation timestamp */
  createdAt: number;
}

/**
 * Pending Canvas operation stored in IndexedDB
 *
 * When a canvas operation fails (e.g., timeout, no client), it's stored here
 * for retry when client reconnects.
 */
export interface PendingCanvasOperation {
  /** Unique operation ID */
  id: string;
  /** Associated workflow ID */
  workflowId: string;
  /** Operation type (e.g., 'canvas_insert') */
  operation: string;
  /** Operation parameters */
  params: Record<string, unknown>;
  /** Number of retry attempts */
  retryCount: number;
  /** Last error message */
  lastError?: string;
  /** Creation timestamp */
  createdAt: number;
  /** Last retry timestamp */
  lastRetryAt?: number;
}

/**
 * Detect existing database version to avoid downgrade errors
 */
function detectDatabaseVersion(): Promise<number> {
  return new Promise((resolve) => {
    // Open without version to get current version
    const request = indexedDB.open(DB_NAME);

    request.onsuccess = () => {
      const db = request.result;
      const version = db.version;
      db.close();
      resolve(Math.max(version, MIN_DB_VERSION));
    };

    request.onerror = () => {
      resolve(MIN_DB_VERSION);
    };
  });
}

/**
 * Check if all required object stores exist
 */
function checkStoresIntegrity(db: IDBDatabase): string[] {
  const missing: string[] = [];
  for (const store of REQUIRED_STORES) {
    if (!db.objectStoreNames.contains(store)) {
      missing.push(store);
    }
  }
  return missing;
}

/**
 * Create missing object stores by incrementing version
 */
function repairDatabase(currentVersion: number): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    // Increment version to trigger onupgradeneeded
    const newVersion = currentVersion + 1;

    const request = indexedDB.open(DB_NAME, newVersion);

    request.onerror = () => {
      console.error('[SWStorage] Failed to repair DB:', request.error);
      reject(request.error);
    };

    request.onsuccess = () => {
      resolve(request.result);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      createAllStores(db);
    };
  });
}

/**
 * Create all required object stores if they don't exist
 */
function createAllStores(db: IDBDatabase): void {
  // Create tasks store
  if (!db.objectStoreNames.contains(TASKS_STORE)) {
    const tasksStore = db.createObjectStore(TASKS_STORE, { keyPath: 'id' });
    tasksStore.createIndex('status', 'status', { unique: false });
    tasksStore.createIndex('type', 'type', { unique: false });
    tasksStore.createIndex('createdAt', 'createdAt', { unique: false });
  }

  // Create config store
  if (!db.objectStoreNames.contains(CONFIG_STORE)) {
    db.createObjectStore(CONFIG_STORE, { keyPath: 'key' });
  }

  // Create workflows store
  if (!db.objectStoreNames.contains(WORKFLOWS_STORE)) {
    const workflowsStore = db.createObjectStore(WORKFLOWS_STORE, {
      keyPath: 'id',
    });
    workflowsStore.createIndex('status', 'status', { unique: false });
    workflowsStore.createIndex('createdAt', 'createdAt', { unique: false });
  }

  // Create chat workflows store
  if (!db.objectStoreNames.contains(CHAT_WORKFLOWS_STORE)) {
    const chatWorkflowsStore = db.createObjectStore(CHAT_WORKFLOWS_STORE, {
      keyPath: 'id',
    });
    chatWorkflowsStore.createIndex('status', 'status', { unique: false });
    chatWorkflowsStore.createIndex('createdAt', 'createdAt', { unique: false });
  }

  // Create pending tool requests store
  if (!db.objectStoreNames.contains(PENDING_TOOL_REQUESTS_STORE)) {
    const pendingRequestsStore = db.createObjectStore(
      PENDING_TOOL_REQUESTS_STORE,
      { keyPath: 'requestId' }
    );
    pendingRequestsStore.createIndex('workflowId', 'workflowId', {
      unique: false,
    });
  }

  // Create pending DOM operations store (for page refresh recovery)
  if (!db.objectStoreNames.contains(PENDING_DOM_OPERATIONS_STORE)) {
    const pendingDomOpsStore = db.createObjectStore(
      PENDING_DOM_OPERATIONS_STORE,
      { keyPath: 'id' }
    );
    pendingDomOpsStore.createIndex('workflowId', 'workflowId', {
      unique: false,
    });
    pendingDomOpsStore.createIndex('chatId', 'chatId', { unique: false });
  }

  // Create task-step mappings store (for unified progress sync)
  if (!db.objectStoreNames.contains(TASK_STEP_MAPPINGS_STORE)) {
    const taskStepMappingsStore = db.createObjectStore(
      TASK_STEP_MAPPINGS_STORE,
      { keyPath: 'taskId' }
    );
    taskStepMappingsStore.createIndex('workflowId', 'workflowId', {
      unique: false,
    });
  }

  // Create pending canvas operations store (for canvas operation retry)
  if (!db.objectStoreNames.contains(PENDING_CANVAS_OPERATIONS_STORE)) {
    const pendingCanvasOpsStore = db.createObjectStore(
      PENDING_CANVAS_OPERATIONS_STORE,
      { keyPath: 'id' }
    );
    pendingCanvasOpsStore.createIndex('workflowId', 'workflowId', {
      unique: false,
    });
  }
}

/**
 * Open IndexedDB connection with dynamic version detection and auto-repair
 */
async function openDB(): Promise<IDBDatabase> {
  // First, detect the current database version
  const targetVersion = await detectDatabaseVersion();

  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, targetVersion);

    request.onerror = () => {
      console.error('[SWStorage] Failed to open DB:', request.error);
      reject(request.error);
    };

    request.onsuccess = () => {
      const db = request.result;

      // Check if all stores exist
      const missingStores = checkStoresIntegrity(db);
      if (missingStores.length > 0) {
        console.warn(
          `[SWStorage] Missing object stores: ${missingStores.join(
            ', '
          )}. Repairing...`
        );
        db.close();

        // Repair by incrementing version
        repairDatabase(db.version).then(resolve).catch(reject);
        return;
      }

      resolve(db);
    };

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      createAllStores(db);
    };
  });
}

/**
 * Task Queue Storage Manager
 */
export class TaskQueueStorage {
  private dbPromise: Promise<IDBDatabase> | null = null;

  // Batch save optimization to reduce IndexedDB transaction overhead
  private pendingTaskSaves: Map<string, SWTask> = new Map();
  private batchSaveTimer: ReturnType<typeof setTimeout> | null = null;
  private batchSavePromises: Map<
    string,
    { resolve: () => void; reject: (err: unknown) => void }
  > = new Map();
  private readonly BATCH_SAVE_DELAY = 50; // ms - batch saves within this window

  /**
   * Get database connection
   */
  private async getDB(): Promise<IDBDatabase> {
    if (!this.dbPromise) {
      this.dbPromise = openDB();
    }
    return this.dbPromise;
  }

  /**
   * Flush pending task saves immediately
   */
  private async flushPendingTaskSaves(): Promise<void> {
    if (this.batchSaveTimer) {
      clearTimeout(this.batchSaveTimer);
      this.batchSaveTimer = null;
    }

    const tasksToSave = Array.from(this.pendingTaskSaves.values());
    const promisesToResolve = new Map(this.batchSavePromises);

    this.pendingTaskSaves.clear();
    this.batchSavePromises.clear();

    if (tasksToSave.length === 0) return;

    try {
      const db = await this.getDB();
      await new Promise<void>((resolve, reject) => {
        const transaction = db.transaction(TASKS_STORE, 'readwrite');
        const store = transaction.objectStore(TASKS_STORE);

        // Put all tasks in a single transaction
        for (const task of tasksToSave) {
          store.put(task);
        }

        transaction.oncomplete = () => {
          // Resolve all pending promises
          promisesToResolve.forEach(({ resolve }) => resolve());
          resolve();
        };
        transaction.onerror = () => {
          const error = transaction.error;
          promisesToResolve.forEach(({ reject }) => reject(error));
          reject(error);
        };
      });
    } catch (error) {
      console.error('[SWStorage] Failed to batch save tasks:', error);
      promisesToResolve.forEach(({ reject }) => reject(error));
    }
  }

  /**
   * Save a task to IndexedDB (batched for performance)
   */
  async saveTask(task: SWTask): Promise<void> {
    return new Promise((resolve, reject) => {
      // Add to pending saves
      this.pendingTaskSaves.set(task.id, task);
      this.batchSavePromises.set(task.id, { resolve, reject });

      // Schedule batch save
      if (!this.batchSaveTimer) {
        this.batchSaveTimer = setTimeout(() => {
          this.flushPendingTaskSaves();
        }, this.BATCH_SAVE_DELAY);
      }
    });
  }

  /**
   * Save a task immediately without batching (for critical saves)
   */
  async saveTaskImmediate(task: SWTask): Promise<void> {
    // First, remove from pending batch if present
    this.pendingTaskSaves.delete(task.id);
    const pendingPromise = this.batchSavePromises.get(task.id);
    if (pendingPromise) {
      this.batchSavePromises.delete(task.id);
    }

    try {
      const db = await this.getDB();
      await new Promise<void>((resolve, reject) => {
        const transaction = db.transaction(TASKS_STORE, 'readwrite');
        const store = transaction.objectStore(TASKS_STORE);
        const request = store.put(task);

        request.onerror = () => reject(request.error);
        request.onsuccess = () => resolve();
      });

      // Resolve the pending promise if it existed
      if (pendingPromise) {
        pendingPromise.resolve();
      }
    } catch (error) {
      console.error('[SWStorage] Failed to save task:', error);
      if (pendingPromise) {
        pendingPromise.reject(error);
      }
      throw error;
    }
  }

  /**
   * Get a task by ID
   */
  async getTask(taskId: string): Promise<SWTask | null> {
    try {
      const db = await this.getDB();
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(TASKS_STORE, 'readonly');
        const store = transaction.objectStore(TASKS_STORE);
        const request = store.get(taskId);

        request.onerror = () => reject(request.error);
        request.onsuccess = () => resolve(request.result || null);
      });
    } catch (error) {
      console.error('[SWStorage] Failed to get task:', error);
      return null;
    }
  }

  /**
   * Get all tasks
   */
  async getAllTasks(): Promise<SWTask[]> {
    try {
      const db = await this.getDB();
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(TASKS_STORE, 'readonly');
        const store = transaction.objectStore(TASKS_STORE);
        const request = store.getAll();

        request.onerror = () => reject(request.error);
        request.onsuccess = () => resolve(request.result || []);
      });
    } catch (error) {
      console.error('[SWStorage] Failed to get all tasks:', error);
      return [];
    }
  }

  /**
   * Get tasks by status
   */
  async getTasksByStatus(status: string): Promise<SWTask[]> {
    try {
      const db = await this.getDB();
      return new Promise((resolve, reject) => {
        const transaction = db.transaction(TASKS_STORE, 'readonly');
        const store = transaction.objectStore(TASKS_STORE);
        const index = store.index('status');
        const request = index.getAll(status);

        request.onerror = () => reject(request.error);
        request.onsuccess = () => resolve(request.result || []);
      });
    } catch (error) {
      console.error('[SWStorage] Failed to get tasks by status:', error);
      return [];
    }
  }

  /**
   * Get tasks with pagination using cursor
   * @param options Pagination options
   * @returns Paginated tasks and metadata
   */
  async getTasksPaginated(options: {
    offset: number;
    limit: number;
    status?: string;
    type?: string;
    sortOrder?: 'asc' | 'desc';
  }): Promise<{ tasks: SWTask[]; total: number; hasMore: boolean }> {
    const { offset, limit, status, type, sortOrder = 'desc' } = options;

    try {
      const db = await this.getDB();

      return new Promise((resolve, reject) => {
        const transaction = db.transaction(TASKS_STORE, 'readonly');
        const store = transaction.objectStore(TASKS_STORE);
        const index = store.index('createdAt');

        // Use cursor to iterate with pagination (filteredTotal is calculated during iteration)
        const direction: IDBCursorDirection =
          sortOrder === 'desc' ? 'prev' : 'next';
        const cursorRequest = index.openCursor(null, direction);

        const tasks: SWTask[] = [];
        let skipped = 0;
        let filteredTotal = 0;

        cursorRequest.onerror = () => reject(cursorRequest.error);
        cursorRequest.onsuccess = (event) => {
          const cursor = (event.target as IDBRequest<IDBCursorWithValue>)
            .result;

          if (!cursor) {
            // No more entries
            resolve({
              tasks,
              total: filteredTotal,
              hasMore: filteredTotal > offset + tasks.length,
            });
            return;
          }

          const task = cursor.value as SWTask;

          // Apply filters
          const matchesStatus = !status || task.status === status;
          const matchesType = !type || task.type === type;

          if (matchesStatus && matchesType) {
            filteredTotal++;

            if (skipped < offset) {
              // Skip items before offset
              skipped++;
            } else if (tasks.length < limit) {
              // Collect items within limit
              tasks.push(task);
            }
          }

          cursor.continue();
        };
      });
    } catch (error) {
      console.error('[SWStorage] Failed to get paginated tasks:', error);
      return { tasks: [], total: 0, hasMore: false };
    }
  }

