  onRemoteId: (taskId: string, remoteId: string) => void;
}

/**
 * Chat handler interface
 */
export interface ChatHandler {
  /** Start streaming chat */
  stream(
    chatId: string,
    params: ChatParams,
    config: GeminiConfig,
    onChunk: (content: string) => void
