/**
 * 错误日志导出工具
 * 聚合 crash-logger + unified-log-service + 崩溃历史，生成 JSON 文件下载
 */

import type { ErrorInfo } from 'react';
import { getDiagnosticData } from '../crash-logger';
import { crashRecoveryService, unifiedLogService } from '@drawnix/drawnix/runtime';

export interface ErrorLogData {
  exportTime: string;
  version: string;
  environment: {
    userAgent: string;
    url: string;
    timestamp: number;
    language: string;
    platform: string;
    screenSize: string;
  };
  currentError?: {
    message: string;
    stack?: string;
    componentStack?: string;
  };
  crashRecovery: ReturnType<typeof crashRecoveryService.getState>;
  diagnostics: ReturnType<typeof getDiagnosticData>;
  unifiedLogs: ReturnType<typeof unifiedLogService.getMemoryLogs>;
}

/**
 * 收集所有诊断数据并触发 JSON 文件下载
 */
export function collectAndDownloadErrorLog(
  error?: Error | null,
  errorInfo?: ErrorInfo | null
): void {
  try {
    const data = collectErrorLogData(error, errorInfo);
    const json = JSON.stringify(data, null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    const a = document.createElement('a');
    a.href = url;
    a.download = `foxvue-error-log-${timestamp}.json`;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();

    // 清理
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 100);
  } catch (e) {
    console.error('[ErrorLogExporter] Failed to export:', e);
  }
}

function collectErrorLogData(
  error?: Error | null,
  errorInfo?: ErrorInfo | null
): ErrorLogData {
  const data: ErrorLogData = {
    exportTime: new Date().toISOString(),
    version: '1.0',
    environment: {
      userAgent: navigator.userAgent,
      url: window.location.href,
      timestamp: Date.now(),
      language: navigator.language,
      platform: navigator.platform,
      screenSize: `${window.screen.width}x${window.screen.height}`,
    },
    crashRecovery: crashRecoveryService.getState(),
    diagnostics: getDiagnosticData(),
    unifiedLogs: unifiedLogService.getMemoryLogs(),
  };

  if (error) {
    data.currentError = {
      message: error.message,
      stack: error.stack,
      componentStack: errorInfo?.componentStack ?? undefined,
    };
  }

  return data;
}

/**
 * 权限策略修复工具
 * 用于解决第三方库触发的 unload 权限策略违规警告
 *
 * 只拦截 unload 事件（影响 bfcache），允许 beforeunload 事件（用于离开提醒）
 */

// 保存原始的 addEventListener 和 removeEventListener
const originalAddEventListener = window.addEventListener.bind(window);
const originalRemoveEventListener = window.removeEventListener.bind(window);

// 存储 beforeunload 监听器的引用
let beforeUnloadHandler: EventListenerOrEventListenerObject | null = null;

window.addEventListener = function(
  type: string,
  listener: EventListenerOrEventListenerObject,
  options?: boolean | AddEventListenerOptions
): any {
  // 只拦截 unload 事件（总是阻止，因为它会影响 bfcache）
  if (type === 'unload') {
    console.warn('[Permissions Policy] Blocked unload event listener');
    return;
  }

  // 对于 beforeunload，保存引用并使用原生方法
  if (type === 'beforeunload') {
    beforeUnloadHandler = listener;
    // console.log('[Permissions Policy] Registering beforeunload with native method');
    return originalAddEventListener.call(window, type as any, listener as any, options);
  }

  // 其他事件正常处理
  return originalAddEventListener.call(window, type as any, listener as any, options);
};

window.removeEventListener = function(
  type: string,
  listener: EventListenerOrEventListenerObject,
  options?: boolean | EventListenerOptions
): any {
  // 对于 beforeunload，清除引用
  if (type === 'beforeunload') {
    beforeUnloadHandler = null;
  }

  return originalRemoveEventListener.call(window, type as any, listener as any, options);
};

// 暴露调试函数
(window as any).__checkBeforeUnload = () => {
  // console.log('[Permissions Policy] beforeUnloadHandler registered:', !!beforeUnloadHandler);
  return !!beforeUnloadHandler;
};

export {};

/**
 * Service Worker Console Log Capture
 *
 * 捕获控制台日志发送给 Service Worker 供调试面板显示。
 * - warn/error: 始终捕获（用于错误追踪）
 * - log/info: 仅在调试模式开启时捕获（用于调试分析）
 */

import { swChannelClient } from '@drawnix/drawnix/runtime';

let isInitialized = false;

// 调试模式：sessionStorage 关掉浏览器自动清除
const DEBUG_STORAGE_KEY = 'sw-debug-enabled';
function getDebugModeFromStorage(): boolean {
  try {
    return sessionStorage.getItem(DEBUG_STORAGE_KEY) === 'true';
  } catch {
    return false;
  }
}
function setDebugModeToStorage(enabled: boolean | undefined): void {
  try {
    sessionStorage.setItem(
      DEBUG_STORAGE_KEY,
      enabled === true ? 'true' : 'false'
    );
  } catch {
    // 忽略
  }
}
let debugModeEnabled = getDebugModeFromStorage();

// 日志队列：channel 未就绪时暂存，就绪后批量发送
interface QueuedLog {
  level: string;
  message: string;
  stack?: string;
}
const logQueue: QueuedLog[] = [];
let initPromise: Promise<void> | null = null;
let nextInitRetryAt = 0;
const INIT_RETRY_COOLDOWN_MS = 15000;
const MAX_LOG_QUEUE_SIZE = 200;

// 保存原始的 console 方法
const originalConsole = {
  error: console.error,
  warn: console.warn,
  info: console.info,
  log: console.log,
  debug: console.debug,
};

function isExpectedFilePickerAbortMessage(message: string): boolean {
  return (
    (message.includes('AbortError') ||
      message.includes('The user aborted a request')) &&
    (message.includes("Failed to execute 'showOpenFilePicker'") ||
      message.includes("Failed to execute 'showSaveFilePicker'") ||
      message.includes('The user aborted a request'))
  );
}

/**
 * 发送日志到 Service Worker
 */
function sendToSW(level: string, message: string, stack?: string) {
  // 防止循环：不转发来自 SW 的日志
  if (
    message.includes('[SW]') ||
    message.includes('[SWTaskQueue]') ||
    message.includes('[SWChannelManager]') ||
    message.includes('[SWChannelClient]') ||
    message.includes('[ServiceWorkerChannel]') ||
    message.includes('Invalid message structure')
  ) {
    return;
  }

  // 过滤监控服务相关的错误（Umami）
  if (
    message.includes('umami.tu-zi.com') ||
    (stack && stack.includes('umami'))
  ) {
    return;
  }

  if (isExpectedFilePickerAbortMessage(message)) {
    return;
  }

  if (
    message.includes(
      'ResizeObserver loop completed with undelivered notifications'
    ) ||
    message.includes('ResizeObserver loop limit exceeded')
  ) {
    return;
  }

  // 发送单条日志
  const doSend = () => {
    if (!swChannelClient.isInitialized()) return;
    swChannelClient
      .reportConsoleLog(
        level,
        [{ message, stack: stack || '', source: window.location.href }],
        Date.now()
      )
      .catch(() => {
        // 忽略发送错误
      });
  };

  // 清空队列中的日志
  const flushQueue = () => {
    while (logQueue.length > 0 && swChannelClient.isInitialized()) {
      const item = logQueue.shift();
      if (!item) {
        continue;
      }
      swChannelClient
        .reportConsoleLog(
          item.level,
          [
            {
              message: item.message,
              stack: item.stack || '',
              source: window.location.href,
            },
          ],
          Date.now()
        )
        .catch(() => undefined);
    }
  };

  const ensureSWChannelReady = () => {
    const now = Date.now();
    if (initPromise || now < nextInitRetryAt) {
      return;
    }

    initPromise = swChannelClient
      .initialize()
      .then((success) => {
        if (!success) {
          nextInitRetryAt = Date.now() + INIT_RETRY_COOLDOWN_MS;
          return;
        }

        nextInitRetryAt = 0;
        flushQueue();
      })
      .catch(() => {
        nextInitRetryAt = Date.now() + INIT_RETRY_COOLDOWN_MS;
      })
      .finally(() => {
        initPromise = null;
      });
  };

  if (swChannelClient.isInitialized()) {
    doSend();
  } else {
    if (logQueue.length >= MAX_LOG_QUEUE_SIZE) {
      logQueue.shift();
    }
    logQueue.push({ level, message, stack });
    ensureSWChannelReady();
  }
}

/**
 * 格式化日志参数为字符串
 */
function formatArgs(args: unknown[]): string {
  return args
    .map((arg) => {
      if (arg instanceof Error) {
        return arg.message;
      }
      if (typeof arg === 'object') {
        try {
          return JSON.stringify(arg);
        } catch {
          return String(arg);
        }
      }
      return String(arg);
    })
    .join(' ');
}

/**
 * 获取 Error 的堆栈信息
 */
function getStack(args: unknown[]): string {
  for (const arg of args) {
    if (arg instanceof Error && arg.stack) {
      return arg.stack;
    }
  }
  return '';
}

/**
 * 初始化控制台日志捕获
 * 只在有 Service Worker 的环境中生效
 */
export function initSWConsoleCapture(): void {
  if (isInitialized) {
    return;
  }

  if (!('serviceWorker' in navigator)) {
    return;
  }

  isInitialized = true;

  // 订阅调试状态变更事件 + 主动触发 channel 连接（否则早期日志会因 channel 未就绪而丢失）
  const setupDebugStatusListener = () => {
    if (swChannelClient.isInitialized()) {
      swChannelClient.subscribeToEvent('debug:statusChanged', (data) => {
        const event = data as { enabled?: boolean; debugModeEnabled?: boolean };
        const enabled = event.enabled ?? event.debugModeEnabled ?? false;
        debugModeEnabled = enabled;
        setDebugModeToStorage(enabled);
      });
      swChannelClient
        .getDebugStatus()
        .then((status: { enabled?: boolean; debugModeEnabled?: boolean }) => {
          const enabled = status.enabled ?? status.debugModeEnabled ?? false;
          debugModeEnabled = enabled;
          setDebugModeToStorage(enabled);
        });
    } else {
      const now = Date.now();
      if (!initPromise && now >= nextInitRetryAt) {
        initPromise = swChannelClient
          .initialize()
          .then((success) => {
            if (!success) {
              nextInitRetryAt = Date.now() + INIT_RETRY_COOLDOWN_MS;
              return;
            }

            nextInitRetryAt = 0;
            while (logQueue.length > 0 && swChannelClient.isInitialized()) {
              const item = logQueue.shift();
              if (!item) {
                continue;
              }
              swChannelClient
                .reportConsoleLog(
                  item.level,
                  [
                    {
                      message: item.message,
                      stack: item.stack || '',
                      source: window.location.href,
                    },
                  ],
                  Date.now()
                )
                .catch(() => undefined);
            }
          })
          .catch(() => {
            nextInitRetryAt = Date.now() + INIT_RETRY_COOLDOWN_MS;
          })
          .finally(() => {
            initPromise = null;
          });
      }
      setTimeout(setupDebugStatusListener, 500);
    }
  };

  setupDebugStatusListener();

  // 拦截 console.error（始终捕获）
  console.error = function (...args: unknown[]) {
    originalConsole.error.apply(console, args);
    sendToSW('error', formatArgs(args), getStack(args));
  };

  // 拦截 console.warn（始终捕获）
  console.warn = function (...args: unknown[]) {
    originalConsole.warn.apply(console, args);
    sendToSW('warn', formatArgs(args), getStack(args));
  };

  // 拦截 console.log（仅调试模式）
  console.log = function (...args: unknown[]) {
    originalConsole.log.apply(console, args);
    if (debugModeEnabled) {
      sendToSW('log', formatArgs(args), '');
    }
  };

  // 拦截 console.info（仅调试模式）
  console.info = function (...args: unknown[]) {
    originalConsole.info.apply(console, args);
    if (debugModeEnabled) {
      sendToSW('info', formatArgs(args), '');
    }
  };

  // 拦截 console.debug（仅调试模式）
  console.debug = function (...args: unknown[]) {
    originalConsole.debug.apply(console, args);
    if (debugModeEnabled) {
      sendToSW('debug', formatArgs(args), '');
    }
  };

  // 监听全局错误
  window.addEventListener('error', (event) => {
    const message = `${event.message} at ${event.filename}:${event.lineno}:${event.colno}`;
    if (isExpectedFilePickerAbortMessage(message)) {
      return;
    }
    sendToSW('error', message, event.error?.stack || '');
  });

  // 监听未捕获的 Promise 错误
  window.addEventListener('unhandledrejection', (event) => {
    const reason = event.reason;
    const message =
      reason instanceof Error
        ? reason.message
        : `Unhandled Promise: ${String(reason)}`;
    const stack = reason instanceof Error ? reason.stack || '' : '';
    if (isExpectedFilePickerAbortMessage(message)) {
      return;
    }
    sendToSW('error', message, stack);
  });

  // sessionStorage 不跨 tab 共享，storage 事件仅对 localStorage 有效，故不监听
}

import { workspaceService } from '@drawnix/drawnix/runtime';
import type { TaskEvent, Task } from '@drawnix/drawnix/task-types';
import {
  createActivities,
  toBoardSummary,
  toTaskSummary,
  type WorkspaceRuntimePort,
  type WorkspaceRuntimeSnapshot,
} from '../domain/workspace-model';

type TaskQueueModule = {
  taskQueueService: {
    getAllTasks: () => Task[];
    cancelTask: (taskId: string) => void;
    retryTask: (taskId: string) => void;
    observeTaskUpdates: () => {
      subscribe: (listener: (event: TaskEvent) => void) => {
        unsubscribe: () => void;
      };
    };
  };
};

let runtimePromise: Promise<TaskQueueModule> | null = null;

function loadTaskQueue(): Promise<TaskQueueModule> {
  runtimePromise ??= import('@drawnix/drawnix/task-queue');
  return runtimePromise;
}

function emptySnapshot(): WorkspaceRuntimeSnapshot {
  return { boards: [], tasks: [], activities: [], updatedAt: 0 };
}

class DrawnixWorkspaceRuntime implements WorkspaceRuntimePort {
  private snapshot: WorkspaceRuntimeSnapshot = emptySnapshot();
  private listeners = new Set<(snapshot: WorkspaceRuntimeSnapshot) => void>();
  private boardSubscription?: { unsubscribe: () => void };
  private taskSubscription?: { unsubscribe: () => void };
  private started = false;

  getSnapshot(): WorkspaceRuntimeSnapshot {
    return this.snapshot;
  }

  async refresh(): Promise<WorkspaceRuntimeSnapshot> {
    await workspaceService.waitForInitialization();
    const boards = workspaceService.getAllBoardMetadata().map(toBoardSummary);
    let tasks: ReturnType<typeof toTaskSummary>[] = [];
    try {
      const { taskQueueService } = await loadTaskQueue();
      tasks = taskQueueService.getAllTasks().map(toTaskSummary);
    } catch (error) {
      console.warn('[WorkspaceRuntime] task projection unavailable:', error);
    }
    this.snapshot = {
      boards: boards.sort((a, b) => b.updatedAt - a.updatedAt),
      tasks: tasks.sort((a, b) => b.updatedAt - a.updatedAt),
      activities: createActivities(boards, tasks),
      updatedAt: Date.now(),
    };
    this.emit();
    this.startSubscriptions();
    return this.snapshot;
  }

  subscribe(
    listener: (snapshot: WorkspaceRuntimeSnapshot) => void
  ): () => void {
    this.listeners.add(listener);
    this.startSubscriptions();
    if (this.snapshot.updatedAt === 0) {
      void this.refresh().catch((error) => {
        console.warn('[WorkspaceRuntime] refresh unavailable:', error);
        this.snapshot = emptySnapshot();
        this.emit();
      });
    } else {
      listener(this.snapshot);
    }
    return () => this.listeners.delete(listener);
  }

  cancelTask(taskId: string): void {
    void loadTaskQueue()
      .then(({ taskQueueService }) => {
        taskQueueService.cancelTask(taskId);
        return this.safeRefresh();
      })
      .catch((error) =>
        console.warn('[WorkspaceRuntime] cancel unavailable:', error)
      );
  }

  retryTask(taskId: string): void {
    void loadTaskQueue()
      .then(({ taskQueueService }) => {
        taskQueueService.retryTask(taskId);
        return this.safeRefresh();
      })
      .catch((error) =>
        console.warn('[WorkspaceRuntime] retry unavailable:', error)
      );
  }

  private startSubscriptions(): void {
    if (this.started) return;
    this.started = true;
    this.boardSubscription = workspaceService.observeEvents().subscribe(() => {
      void this.safeRefresh();
    });
    void loadTaskQueue()
      .then(({ taskQueueService }) => {
        this.taskSubscription = taskQueueService
          .observeTaskUpdates()
          .subscribe(() => {
            void this.safeRefresh();
          });
      })
      .catch((error) =>
        console.warn('[WorkspaceRuntime] task subscription unavailable:', error)
      );
  }

  private async safeRefresh(): Promise<void> {
    try {
      await this.refresh();
    } catch (error) {
      console.warn(
        '[WorkspaceRuntime] subscription refresh unavailable:',
        error
      );
    }
  }

  private emit(): void {
    this.listeners.forEach((listener) => listener(this.snapshot));
  }
}

export const drawnixWorkspaceRuntime: WorkspaceRuntimePort =
  new DrawnixWorkspaceRuntime();

